using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — resolves any public type.
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1️⃣  GetTypeInfo<T>() — returns JsonTypeInfo<T> directly (no cast needed).
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>  →  Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 38), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2️⃣  TryGetTypeInfo<T>() — probe without throwing.

// 2a. Type the resolver CAN handle:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
    Console.WriteLine($"TryGet Person: found ({found!.Type.Name})");
else
    Console.WriteLine("TryGet Person: not found");

// 2b. Build options that use a source-gen context containing ONLY WeatherForecast.
//     Asking for Person will return false instead of throwing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = WeatherContext.Default
};

if (limited.TryGetTypeInfo<Person>(out _))
    Console.WriteLine("TryGet Person on limited resolver: found");
else
    Console.WriteLine("TryGet Person on limited resolver: NOT found (expected)");

if (limited.TryGetTypeInfo<WeatherForecast>(out JsonTypeInfo<WeatherForecast>? wf))
    Console.WriteLine($"TryGet WeatherForecast on limited resolver: found ({wf!.Type.Name})");

